using Kuvik.ONDC.Api.Configuration;
using Kuvik.ONDC.Api.Models.Common;
using Microsoft.Extensions.Options;
namespace Kuvik.ONDC.Api.Services.Validation;
public interface IFis12Validator { void Validate(OndcEnvelope request,string expectedAction); }
public sealed class Fis12Validator(IOptions<OndcOptions> options) : IFis12Validator { public void Validate(OndcEnvelope r,string action) { var c=r.Context; var o=options.Value; if(c.Domain!=o.Domain||c.Version!=o.Version) throw new ArgumentException("Unsupported ONDC domain or FIS version."); if(c.Action!=action) throw new ArgumentException($"Expected ONDC action '{action}'."); if(c.Location.Country.Code!="IND"||String.IsNullOrWhiteSpace(c.Location.City.Code)) throw new ArgumentException("Context location must contain IND and a city code."); if(!Guid.TryParse(c.TransactionId,out _)||!Guid.TryParse(c.MessageId,out _)) throw new ArgumentException("transaction_id and message_id must be UUIDs."); if(c.Timestamp == default || Math.Abs((DateTimeOffset.UtcNow-c.Timestamp).TotalMinutes)>15) throw new ArgumentException("Context timestamp is outside the accepted window."); if(String.IsNullOrWhiteSpace(c.BapId)||!Uri.TryCreate(c.BapUri,UriKind.Absolute,out _)) throw new ArgumentException("BAP identity is invalid."); if(r.Message.ValueKind!=System.Text.Json.JsonValueKind.Object) throw new ArgumentException("message must be an object."); ValidateMessage(r.Message,action); }
 static void ValidateMessage(System.Text.Json.JsonElement m,string action) { bool Has(string p)=>m.TryGetProperty(p,out _); if(action=="search") { if(!m.TryGetProperty("intent",out var i)||!i.TryGetProperty("category",out var category)||!category.TryGetProperty("descriptor",out var descriptor)||!descriptor.TryGetProperty("code",out var code)||code.GetString()!="PERSONAL_LOAN") throw new ArgumentException("FIS12 offline search requires intent.category.descriptor.code PERSONAL_LOAN."); } else if(action=="select"||action=="confirm") { if(!m.TryGetProperty("order",out var order)||!order.TryGetProperty("provider",out var provider)||!provider.TryGetProperty("id",out _)||!order.TryGetProperty("items",out var items)||items.GetArrayLength()==0) throw new ArgumentException($"FIS12 {action} requires order.provider.id and at least one item."); } else if(action=="status" && !Has("ref_id")) throw new ArgumentException("FIS12 status requires message.ref_id."); else if(action.StartsWith("on_") && !Has("catalog") && !Has("order") && !Has("ack")) throw new ArgumentException("Callback message does not contain the action payload."); } }
